    size_t namelen;
    uint32_t type;
    uint32_t ndim;
    uint64_t dim[GGUF_TENSOR_MAX_DIM]; /* Fixed 8-element array */
    uint64_t offset;
    uint64_t bsize;
    uint64_t num_weights;
    uint8_t *weights_data;
